// Inlined views and styles to guarantee 0 filesystem errors in serverless environments
export const formHtml = "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"description\" content=\"Kirim curhatan atau pesan anonim di Menfesskan, otomatis tayang di feed Instagram.\">\n  <title>Menfesskan</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Bungee&family=Chivo:wght@400;700;900&family=Silkscreen:wght@700&display=swap\" rel=\"stylesheet\">\n  <style>\n/* Hallmark · shape: Workbench · genre: playful · theme: Arcade (deal 3/3, seed retro-menfess-confession-platform-4983·637d30ec·2026-11-16·r0) · job: try · draw: 637d30ec\n * hero: Stage · nav: edge-aligned · footer: mast · imagery: none · signature: tactile CRT confession terminal · arcade: ember/grille\n * axes: dark/pixel/chromatic-ember · posture: full-palette · contrast: pass · fold: pass · v2.0.0 */\n@import url(\"/styles/page.css\");\n\nhtml, body {\n  overflow-x: clip;\n}\n\n:focus-visible {\n  outline: 2px solid var(--color-focus);\n  outline-offset: 2px;\n}\n\nbutton:active, .btn-arcade:active {\n  translate: 3px 3px;\n}\n\nbutton:disabled, .btn-arcade:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n  </style>\n</head>\n<body class=\"crt\">\n  <main class=\"arcade-viewport\">\n    <!-- Center Confession Terminal -->\n    <section class=\"confession-cabinet\">\n      <div class=\"cabinet-lead\">\n        <h1 class=\"cabinet-title\">Menfesskan</h1>\n        <p class=\"cabinet-subtitle\">\n          Kirim curhatan atau pesan anonim. Otomatis tayang di feed Instagram.\n        </p>\n      </div>\n\n      <div id=\"alertBox\" class=\"arcade-alert\" hidden></div>\n\n      <form id=\"menfessForm\" class=\"form-group\" enctype=\"multipart/form-data\">\n        <!-- 1. Text Confession -->\n        <div class=\"form-label\">\n          <label for=\"content\">Pesan Menfess</label>\n          <span id=\"charCount\" class=\"char-counter\">0 / 800 CHARS</span>\n        </div>\n\n        <textarea\n          id=\"content\"\n          name=\"content\"\n          rows=\"4\"\n          placeholder=\"Tulis pesan atau curhatan kamu di sini… Identitas kamu tidak disimpan.\"\n          class=\"confession-input\"\n          maxlength=\"800\"\n          required\n        ></textarea>\n\n        <!-- 2. Songfess (Lagu Pengiring) -->\n        <div class=\"form-label\" style=\"margin-top: var(--space-xs);\">\n          <label for=\"songQuery\">Lagu Pengiring (Opsional)</label>\n          <span class=\"field-hint\">Songfess</span>\n        </div>\n        <input\n          type=\"text\"\n          id=\"songQuery\"\n          name=\"song_query\"\n          class=\"confession-text-input\"\n          placeholder=\"Cari lagu di Instagram… cth: Nadin Amizah - Rayuan Perempuan Gila\"\n          maxlength=\"150\"\n        />\n\n        <!-- 3. Photo Attachments (Carousel Slides) -->\n        <div class=\"form-label\" style=\"margin-top: var(--space-xs);\">\n          <label for=\"imageAttachments\">Lampiran Foto (Maks 4 Foto, 2MB/foto)</label>\n          <span id=\"slideBadge\" class=\"slide-badge\">1 SLIDE</span>\n        </div>\n\n        <div class=\"file-dropzone\">\n          <input\n            type=\"file\"\n            id=\"imageAttachments\"\n            name=\"images\"\n            accept=\"image/jpeg,image/png,image/webp\"\n            multiple\n            class=\"file-input-hidden\"\n          />\n          <label for=\"imageAttachments\" class=\"file-dropzone-label\" tabindex=\"0\">\n            <span>📷 + Tambah Foto Lampiran (Maks 4)</span>\n          </label>\n        </div>\n\n        <div id=\"previewContainer\" class=\"thumbnail-grid\" hidden></div>\n\n        <!-- 4. Submit Button -->\n        <button type=\"submit\" id=\"submitBtn\" class=\"btn-arcade\" style=\"margin-top: var(--space-sm);\">\n          <span id=\"btnText\">Kirim Menfess</span>\n        </button>\n      </form>\n\n      <!-- Rules Box -->\n      <aside class=\"rules-tape\" aria-label=\"Aturan Pengiriman\">\n        <div class=\"rules-heading\">Aturan Menfess:</div>\n        <ul class=\"rules-list\">\n          <li>Tanpa nomor telepon atau kontak pribadi (anti-doxxing).</li>\n          <li>Bebas ujaran kebencian, SARA, dan konten vulgar.</li>\n          <li>Maksimal 4 foto pendukung (ukuran maks 2MB per foto).</li>\n          <li>Pesan & lagu yang lolos verifikasi langsung diproses ke Instagram.</li>\n        </ul>\n      </aside>\n    </section>\n\n    <!-- Footer -->\n    <footer class=\"arcade-footer\">\n      <span>Anonimitas 100% terjaga.</span>\n      <button type=\"button\" id=\"openLegalModal\" class=\"legal-link-btn\">\n        Ketentuan & Takedown\n      </button>\n    </footer>\n  </main>\n\n  <!-- Legal & Takedown Dialog -->\n  <dialog id=\"legalModal\" class=\"arcade-modal\" aria-labelledby=\"legalTitle\">\n    <div class=\"modal-box\">\n      <div class=\"modal-header\">\n        <h2 id=\"legalTitle\" class=\"modal-title\">Ketentuan Hukum & Takedown</h2>\n        <button type=\"button\" id=\"closeLegalModal\" class=\"modal-close-btn\" aria-label=\"Tutup ketentuan\">×</button>\n      </div>\n      <div class=\"modal-body\">\n        <p>\n          <strong>1. Tanggung Jawab Pengirim</strong><br>\n          Berdasarkan UU ITE, seluruh isi pesan merupakan tanggung jawab mutlak pengirim. Menfesskan bertindak sebagai perantara netral dan tidak memproduksi konten kiriman pengguna.\n        </p>\n        <p>\n          <strong>2. Larangan Doxxing (UU PDP)</strong><br>\n          Dilarang menyebarkan nomor telepon, alamat, akun pribadi, atau identitas orang lain tanpa izin tertulis (UU Pelindungan Data Pribadi).\n        </p>\n        <p>\n          <strong>3. Prosedur Takedown Konten</strong><br>\n          Pihak yang merasa dirugikan atas postingan tertentu berhak meminta penghapusan kapan saja melalui DM Instagram resmi kami dengan menyebutkan ID menfess. Moderator memproses penghapusan maksimal 1x24 jam.\n        </p>\n      </div>\n      <div class=\"modal-footer\">\n        <button type=\"button\" id=\"confirmLegalBtn\" class=\"btn-arcade\" style=\"min-height: 44px; padding: var(--space-xs) var(--space-md); font-size: var(--text-sm);\">\n          Saya Mengerti\n        </button>\n      </div>\n    </div>\n  </dialog>\n\n  <script>\n    const textarea = document.getElementById('content');\n    const songInput = document.getElementById('songQuery');\n    const fileInput = document.getElementById('imageAttachments');\n    const previewContainer = document.getElementById('previewContainer');\n    const slideBadge = document.getElementById('slideBadge');\n    const charCount = document.getElementById('charCount');\n    const form = document.getElementById('menfessForm');\n    const submitBtn = document.getElementById('submitBtn');\n    const btnText = document.getElementById('btnText');\n    const alertBox = document.getElementById('alertBox');\n\n    // Legal Modal Elements\n    const legalModal = document.getElementById('legalModal');\n    const openLegalBtn = document.getElementById('openLegalModal');\n    const closeLegalBtn = document.getElementById('closeLegalModal');\n    const confirmLegalBtn = document.getElementById('confirmLegalBtn');\n\n    openLegalBtn.addEventListener('click', () => legalModal.showModal());\n    const closeModal = () => legalModal.close();\n    closeLegalBtn.addEventListener('click', closeModal);\n    confirmLegalBtn.addEventListener('click', closeModal);\n    legalModal.addEventListener('click', (e) => {\n      if (e.target === legalModal) closeModal();\n    });\n\n    textarea.addEventListener('input', () => {\n      charCount.textContent = `${textarea.value.length} / 800 CHARS`;\n    });\n\n    function showAlert(msg, isSuccess = true) {\n      alertBox.textContent = msg;\n      alertBox.className = `arcade-alert ${isSuccess ? 'arcade-alert--success' : 'arcade-alert--error'}`;\n      alertBox.removeAttribute('hidden');\n    }\n\n    // File Attachments Management (Max 4, Max 2MB each, Max 3.8MB total)\n    let selectedFiles = [];\n    const MAX_FILES = 4;\n    const MAX_SIZE_BYTES = 2 * 1024 * 1024; // 2MB\n    const MAX_TOTAL_BYTES = 3.8 * 1024 * 1024; // 3.8MB to stay within Vercel's 4.5MB limit\n\n    function updateBadgeAndPreviews() {\n      const totalSlides = 1 + selectedFiles.length;\n      slideBadge.textContent = totalSlides === 1 ? '1 SLIDE (TEKS)' : `${totalSlides} SLIDES (1 TEKS + ${selectedFiles.length} FOTO)`;\n\n      previewContainer.innerHTML = '';\n      if (selectedFiles.length === 0) {\n        previewContainer.setAttribute('hidden', '');\n        return;\n      }\n\n      previewContainer.removeAttribute('hidden');\n      selectedFiles.forEach((file, idx) => {\n        const item = document.createElement('div');\n        item.className = 'thumbnail-item';\n\n        const img = document.createElement('img');\n        img.className = 'thumbnail-img';\n        img.alt = `Slide ${idx + 2}`;\n        img.src = URL.createObjectURL(file);\n\n        const rmBtn = document.createElement('button');\n        rmBtn.type = 'button';\n        rmBtn.className = 'thumbnail-remove-btn';\n        rmBtn.setAttribute('aria-label', `Hapus foto ${idx + 1}`);\n        rmBtn.textContent = '×';\n        rmBtn.addEventListener('click', () => {\n          selectedFiles.splice(idx, 1);\n          updateBadgeAndPreviews();\n        });\n\n        item.appendChild(img);\n        item.appendChild(rmBtn);\n        previewContainer.appendChild(item);\n      });\n    }\n\n    fileInput.addEventListener('change', () => {\n      const files = Array.from(fileInput.files);\n      for (const f of files) {\n        if (selectedFiles.length >= MAX_FILES) {\n          showAlert(`Maksimal ${MAX_FILES} foto lampiran.`, false);\n          break;\n        }\n        if (f.size > MAX_SIZE_BYTES) {\n          showAlert(`File \"${f.name}\" melebihi batas 2MB. Silakan pilih foto lain.`, false);\n          continue;\n        }\n        const currentTotal = selectedFiles.reduce((acc, curr) => acc + curr.size, 0);\n        if (currentTotal + f.size > MAX_TOTAL_BYTES) {\n          showAlert(`Total ukuran semua foto melebihi batas 3.8MB. Kurangi foto atau kompres terlebih dahulu.`, false);\n          break;\n        }\n        if (!['image/jpeg', 'image/png', 'image/webp'].includes(f.type)) {\n          showAlert(`Format file \"${f.name}\" tidak didukung. Gunakan JPG, PNG, atau WebP.`, false);\n          continue;\n        }\n        selectedFiles.push(f);\n      }\n      fileInput.value = '';\n      updateBadgeAndPreviews();\n    });\n\n    form.addEventListener('submit', async (e) => {\n      e.preventDefault();\n      const content = textarea.value.trim();\n      if (!content) return;\n\n      submitBtn.disabled = true;\n      btnText.textContent = 'Mengunggah…';\n      alertBox.setAttribute('hidden', '');\n\n      try {\n        const formData = new FormData();\n        formData.append('content', content);\n        if (songInput.value.trim()) {\n          formData.append('song_query', songInput.value.trim());\n        }\n        selectedFiles.forEach((f) => {\n          formData.append('images', f);\n        });\n\n        const res = await fetch('/api/menfess', {\n          method: 'POST',\n          body: formData,\n        });\n\n        let data = null;\n        const contentType = res.headers.get('content-type') || '';\n        if (contentType.includes('application/json')) {\n          data = await res.json();\n        } else {\n          const rawText = await res.text();\n          throw new Error(`HTTP ${res.status}: ${rawText.slice(0, 120) || res.statusText || 'Server Error'}`);\n        }\n\n        if (res.ok && data.success) {\n          if (data.status === 'queued') {\n            const songNote = data.song_query ? ` dengan lagu \"${data.song_query}\"` : '';\n            showAlert(`Menfess kamu (${data.slidesCount || 1} slide)${songNote} berhasil masuk antrean postingan!`, true);\n          } else if (data.status === 'posted') {\n            showAlert('Pesan kamu berhasil dikirim ke feed Instagram.', true);\n          } else if (data.status === 'flagged') {\n            showAlert('Pesan menunggu verifikasi moderator: ' + (data.flagReason || 'Pemeriksaan keamanan'), true);\n          }\n          textarea.value = '';\n          songInput.value = '';\n          selectedFiles = [];\n          charCount.textContent = '0 / 800 CHARS';\n          updateBadgeAndPreviews();\n        } else {\n          showAlert(data?.error || `Error ${res.status}: Pesan gagal dikirim.`, false);\n        }\n      } catch (err) {\n        console.error('[Menfess Submit Error]', err);\n        const errMsg = err?.message || 'Gagal mengirim pesan.';\n        showAlert(`Gagal mengirim: ${errMsg}`, false);\n      } finally {\n        submitBtn.disabled = false;\n        btnText.textContent = 'Kirim Menfess';\n      }\n    });\n  </script>\n</body>\n</html>\n";

export const adminHtml = "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <meta name=\"description\" content=\"Dashboard moderator menfess untuk monitoring dan kurasi konten.\">\n  <title>Admin Dashboard Menfess</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Bungee&family=Chivo:wght@400;700;900&family=Silkscreen:wght@700&display=swap\" rel=\"stylesheet\">\n  <style>\n/* Hallmark · shape: Workbench · genre: playful · theme: Arcade (deal 3/3, seed retro-menfess-confession-platform-4983·637d30ec·2026-11-16·r0) · job: try · draw: 637d30ec\n * hero: Stage · nav: edge-aligned · footer: mast · imagery: none · signature: tactile admin moderator table · arcade: ember/grille\n * axes: dark/pixel/chromatic-ember · posture: full-palette · contrast: pass · fold: pass · v2.0.0 */\n/* Hallmark · pre-emit critique: P5 H5 E5 S5 R5 V5 · weakest: S, strict tokenized admin surface */\n@import url(\"/styles/admin.css\");\n\nhtml, body {\n  overflow-x: clip;\n}\n\n:focus-visible {\n  outline: 2px solid var(--color-focus);\n  outline-offset: 2px;\n}\n\nbutton:active {\n  translate: 2px 2px;\n}\n\nbutton:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n  </style>\n</head>\n<body class=\"crt\">\n  <main class=\"admin-layout\">\n    <!-- Top Bar -->\n    <header class=\"admin-header\">\n      <div>\n        <h1 class=\"admin-title\">Menfess Moderator</h1>\n        <p class=\"admin-desc\">Pantau feed, kurasi pesan tertahan, dan takedown postingan Instagram.</p>\n      </div>\n\n      <!-- Quota Counter -->\n      <div class=\"quota-box\">\n        <div class=\"quota-meta\">\n          <span class=\"quota-label\">Kuota 24 Jam Meta</span>\n          <span id=\"quotaText\" class=\"quota-num\">-- / 25</span>\n        </div>\n        <div class=\"quota-bar-track\">\n          <div id=\"quotaBar\" class=\"quota-bar-fill\"></div>\n        </div>\n      </div>\n    </header>\n\n    <!-- Auth Key Input -->\n    <section class=\"auth-bar\" aria-label=\"Autentikasi Admin\">\n      <label for=\"adminPassword\" class=\"visually-hidden\">Password Admin</label>\n      <input\n        type=\"password\"\n        id=\"adminPassword\"\n        placeholder=\"Masukkan ADMIN_PASSWORD…\"\n        class=\"admin-input\"\n      />\n      <button id=\"savePasswordBtn\" class=\"admin-btn\">\n        Simpan Kunci\n      </button>\n      <span id=\"authStatus\" class=\"quota-label\">Kunci tersimpan di browser</span>\n      <div style=\"margin-left: auto;\">\n        <a href=\"/\" class=\"quota-label\" style=\"text-decoration: underline;\">Form Pengirim</a>\n      </div>\n    </section>\n\n    <!-- Filter Tabs -->\n    <nav class=\"tab-row\" aria-label=\"Filter Status\">\n      <button onclick=\"setFilter('')\" class=\"tab-btn\" data-filter=\"\" data-active=\"true\">Semua</button>\n      <button onclick=\"setFilter('flagged')\" class=\"tab-btn\" data-filter=\"flagged\">Karantina</button>\n      <button onclick=\"setFilter('posted')\" class=\"tab-btn\" data-filter=\"posted\">Terbit</button>\n      <button onclick=\"setFilter('rejected')\" class=\"tab-btn\" data-filter=\"rejected\">Ditolak</button>\n    </nav>\n\n    <!-- Menfess List Container -->\n    <div id=\"listContainer\" class=\"space-y-4\">\n      <div class=\"empty-state\">Memuat data menfess…</div>\n    </div>\n  </main>\n\n  <script>\n    let currentFilter = '';\n    const passwordInput = document.getElementById('adminPassword');\n    const authStatus = document.getElementById('authStatus');\n\n    const saved = localStorage.getItem('menfess_admin_pwd') || '';\n    if (saved) passwordInput.value = saved;\n\n    document.getElementById('savePasswordBtn').addEventListener('click', () => {\n      localStorage.setItem('menfess_admin_pwd', passwordInput.value);\n      authStatus.textContent = 'Kunci diperbarui';\n      setTimeout(() => {\n        authStatus.textContent = 'Kunci tersimpan di browser';\n      }, 2000);\n      loadData();\n    });\n\n    function getHeaders() {\n      return {\n        'Content-Type': 'application/json',\n        'Authorization': `Bearer ${passwordInput.value || localStorage.getItem('menfess_admin_pwd') || ''}`,\n      };\n    }\n\n    function setFilter(filter) {\n      currentFilter = filter;\n      document.querySelectorAll('.tab-btn').forEach(btn => {\n        if (btn.dataset.filter === filter) {\n          btn.setAttribute('data-active', 'true');\n        } else {\n          btn.removeAttribute('data-active');\n        }\n      });\n      loadData();\n    }\n\n    async function loadData() {\n      const container = document.getElementById('listContainer');\n      try {\n        const url = `/api/admin/menfess?status=${currentFilter}`;\n        const res = await fetch(url, { headers: getHeaders() });\n\n        if (res.status === 401) {\n          container.innerHTML = `\n            <div class=\"empty-state\" style=\"color: var(--color-error); border-color: var(--color-error);\">\n              Password admin belum diisi atau salah. Masukkan password yang sesuai lalu klik Simpan Kunci.\n            </div>\n          `;\n          return;\n        }\n\n        const data = await res.json();\n        renderQuota(data.quotaToday || 0);\n        renderList(data.records || []);\n      } catch (err) {\n        container.innerHTML = `<div class=\"empty-state\">Gagal memuat data. Periksa koneksi backend.</div>`;\n      }\n    }\n\n    function renderQuota(count) {\n      const text = document.getElementById('quotaText');\n      const bar = document.getElementById('quotaBar');\n      text.textContent = `${count} / 25`;\n      const pct = Math.min(100, Math.round((count / 25) * 100));\n      bar.style.transform = `scaleX(${pct / 100})`;\n      if (count >= 25) {\n        bar.style.background = 'var(--color-error)';\n        text.style.color = 'var(--color-error)';\n      } else {\n        bar.style.background = 'var(--color-accent-2)';\n        text.style.color = 'var(--color-accent-2)';\n      }\n    }\n\n    function renderList(records) {\n      const container = document.getElementById('listContainer');\n      if (!records.length) {\n        container.innerHTML = `<div class=\"empty-state\">Tidak ada menfess pada kategori ini.</div>`;\n        return;\n      }\n\n      container.innerHTML = records.map(r => {\n        let badgeMod = 'status-badge--posted';\n        if (r.status === 'flagged') badgeMod = 'status-badge--flagged';\n        if (r.status === 'rejected') badgeMod = 'status-badge--rejected';\n\n        const date = new Date(r.created_at).toLocaleString('id-ID');\n\n        return `\n          <article class=\"record-card\">\n            <div class=\"record-top\">\n              <span class=\"status-badge ${badgeMod}\">\n                ${r.status.toUpperCase()}\n              </span>\n              <span class=\"quota-label\">#${r.id.slice(0, 8)} · ${date}</span>\n            </div>\n\n            <div class=\"record-content\">${escapeHtml(r.content)}</div>\n\n            ${r.flag_reason ? `\n              <div class=\"flag-alert\">\n                Perhatian: ${escapeHtml(r.flag_reason)}\n              </div>\n            ` : ''}\n\n            <div class=\"record-actions\">\n              <div class=\"record-links\">\n                ${r.ig_permalink ? `\n                  <a href=\"${r.ig_permalink}\" target=\"_blank\">Buka di Instagram</a>\n                ` : ''}\n                ${r.image_url ? `\n                  <a href=\"${r.image_url}\" target=\"_blank\">Lihat Kartu Gambar</a>\n                ` : ''}\n              </div>\n\n              <div style=\"display: flex; gap: var(--space-xs); margin-left: auto;\">\n                ${r.status === 'flagged' ? `\n                  <button onclick=\"approveMenfess('${r.id}')\" class=\"admin-btn admin-btn--success\">\n                    Setujui dan Post\n                  </button>\n                  <button onclick=\"rejectMenfess('${r.id}')\" class=\"admin-btn admin-btn--danger\">\n                    Tolak\n                  </button>\n                ` : ''}\n\n                ${r.status === 'posted' ? `\n                  <button onclick=\"takedownMenfess('${r.id}')\" class=\"admin-btn admin-btn--danger\">\n                    Takedown IG\n                  </button>\n                ` : ''}\n              </div>\n            </div>\n          </article>\n        `;\n      }).join('');\n    }\n\n    function escapeHtml(text) {\n      return text.replace(/[&<>\"']/g, m => ({\n        '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#039;'\n      }[m]));\n    }\n\n    async function approveMenfess(id) {\n      if (!confirm('Posting menfess ini ke Instagram sekarang?')) return;\n      try {\n        const res = await fetch(`/api/admin/menfess/${id}/approve`, {\n          method: 'POST',\n          headers: getHeaders(),\n        });\n        const data = await res.json();\n        if (data.success) {\n          alert('Berhasil diposting ke Instagram.');\n          loadData();\n        } else {\n          alert(data.error || 'Gagal posting.');\n        }\n      } catch (e) {\n        alert('Gagal menghubungi server.');\n      }\n    }\n\n    async function rejectMenfess(id) {\n      if (!confirm('Tolak menfess ini?')) return;\n      try {\n        await fetch(`/api/admin/menfess/${id}/reject`, {\n          method: 'POST',\n          headers: getHeaders(),\n        });\n        loadData();\n      } catch (e) {\n        alert('Gagal menolak menfess.');\n      }\n    }\n\n    async function takedownMenfess(id) {\n      if (!confirm('Yakin ingin menghapus postingan ini dari Instagram (Takedown)?')) return;\n      try {\n        const res = await fetch(`/api/admin/menfess/${id}/takedown`, {\n          method: 'POST',\n          headers: getHeaders(),\n        });\n        const data = await res.json();\n        if (data.success) {\n          alert('Postingan berhasil di-takedown dari Instagram.');\n          loadData();\n        } else {\n          alert(data.error || 'Gagal takedown.');\n        }\n      } catch (e) {\n        alert('Gagal takedown.');\n      }\n    }\n\n    loadData();\n  </script>\n</body>\n</html>\n";

